using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using System.Linq;
using System.Threading.Tasks;
using Vivet.AI.Services.Interfaces;
using Vivet.AI.Services.Models.Blobs;
using Vivet.AI.Services.Models.Blobs.Data;
using Vivet.AI.Services.Models.MimeTypes;
using Vivet.AI.Services.Requests.Transcription;

namespace IntegrationTests.Vivet.AI.Services;

[TestClass]
public class TranscriptionServiceTests : BaseTests
{
    private ITranscriptionService TranscriptionService => this.ServiceProvider.GetRequiredService<ITranscriptionService>();

    [TestMethod]
    public async Task TranscribeTest()
    {
        const string BASE_64 = "";
        const string EXPECTED = "Cinderella is a young woman who lived with her cruel stepmother and stepsisters, who treat her as a servant in her own home. Despite her hardships, she remains kind and hopeful, dreaming of a better life. One day an invitation arrives for a royal ball, giving her a chance to change her fate.";

        var response = await this.TranscriptionService
            .Transcribe(new TranscribeRequest
            {
                Blob = new AudioBlob
                {
                    Data = new BlobDataBase64
                    {
                        Base64 = BASE_64
                    },
                    MimeType = AudioMimeType.M4A
                }
            });

        Assert.IsNotNull(response);

        var transcribedText = response.Texts.FirstOrDefault();
        Assert.IsNotNull(transcribedText);
        Assert.AreEqual(EXPECTED, transcribedText.Content);
        Assert.AreEqual("english", transcribedText.Language);
        Assert.IsNotNull(transcribedText.StartTime);
        Assert.IsNotNull(transcribedText.EndTime);
        Assert.IsNotNull(transcribedText.Duration);

        var expecteds = EXPECTED.Split('.');
        var transcribedSegments = transcribedText.Segments.ToArray();

        Assert.AreEqual(3, transcribedSegments.Length);

        for (var i = 0; i < transcribedSegments.Length; i++)
        {
            var expected = expecteds[i].Trim();
            var transcribedSegment = transcribedSegments[i];

            Assert.AreEqual(expected.Trim(), transcribedSegment.Content.Replace(".", ""));
            Assert.IsNotNull(transcribedSegment.StartTime);
            Assert.IsNotNull(transcribedSegment.EndTime);
            Assert.IsNotNull(transcribedSegment.Duration);
            Assert.IsEmpty(transcribedSegment.Words);

            i++;
        }
    }

    [TestMethod]
    public async Task TranscribeWhenWordGranularityTest()
    {
        const string BASE_64 = "";
        const string EXPECTED = "Cinderella is a young woman who lived with her cruel stepmother and stepsisters, who treat her as a servant in her own home. Despite her hardships, she remains kind and hopeful, dreaming of a better life. One day an invitation arrives for a royal ball, giving her a chance to change her fate.";

        var response = await this.TranscriptionService
            .Transcribe(new TranscribeRequest
            {
                Blob = new AudioBlob
                {
                    Data = new BlobDataBase64
                    {
                        Base64 = BASE_64
                    },
                    MimeType = AudioMimeType.M4A
                },
                ConfigOverrides =
                {
                    IncludeWordGranularity = true
                }
            });

        Assert.IsNotNull(response);

        var transcribedText = response.Texts.FirstOrDefault();
        Assert.IsNotNull(transcribedText);
        Assert.AreEqual(EXPECTED, transcribedText.Content);
        Assert.AreEqual("english", transcribedText.Language);
        Assert.IsNotNull(transcribedText.StartTime);
        Assert.IsNotNull(transcribedText.EndTime);
        Assert.IsNotNull(transcribedText.Duration);

        var expecteds = EXPECTED.Split('.');
        var transcribedSegments = transcribedText.Segments.ToArray();

        Assert.AreEqual(3, transcribedSegments.Length);

        for (var i = 0; i < transcribedSegments.Length; i++)
        {
            var expected = expecteds[i].Trim();
            var transcribedSegment = transcribedSegments[i];

            Assert.AreEqual(expected.Trim(), transcribedSegment.Content.Replace(".", ""));
            Assert.IsNotNull(transcribedSegment.StartTime);
            Assert.IsNotNull(transcribedSegment.EndTime);
            Assert.IsNotNull(transcribedSegment.Duration);

            var expectedWords = expected.Split(' ');
            var transcribedWords = transcribedSegment.Words.ToArray();

            for (var j = 0; j < transcribedWords.Length; j++)
            {
                var expectedWord = expectedWords[j].Trim();
                var transcribedWord = transcribedWords[j];

                Assert.AreEqual(expectedWord.Replace(",", ""), transcribedWord.Content);
                Assert.IsNotNull(transcribedWord.StartTime);
                Assert.IsNotNull(transcribedText.EndTime);
                Assert.IsNotNull(transcribedText.Duration);

                j++;
            }

            i++;
        }
    }
}